import {
  ChangeDetectionStrategy,
  Component,
  booleanAttribute,
  computed,
  input,
  model,
  output,
  signal,
} from '@angular/core';
export interface AevkoCommandItem {
  id: string;
  label: string;
  description?: string;
  group?: string;
  shortcut?: string;
  disabled?: boolean;
  keywords?: readonly string[];
}
@Component({
  selector: 'aevko-command',
  standalone: true,
  templateUrl: './command.component.html',
  styleUrl: './command.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    'data-slot': 'command',
    '[attr.data-disabled]': 'disabled() ? "true" : null',
  },
})
export class AevkoCommand {
  readonly id = input('aevko-command');
  readonly label = input('Command menu');
  readonly placeholder = input('Type a command or search…');
  readonly items = input.required<readonly AevkoCommandItem[]>();
  readonly query = model('');
  readonly value = model('');
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly activated = output<AevkoCommandItem>();
  protected readonly active = signal(0);
  protected readonly filtered = computed(() => {
    const query = this.query().trim().toLocaleLowerCase();
    return this.items().filter(
      (item) =>
        !query ||
        [item.label, item.description, ...(item.keywords ?? [])]
          .filter(Boolean)
          .join(' ')
          .toLocaleLowerCase()
          .includes(query),
    );
  });
  protected readonly enabledItems = computed(() =>
    this.filtered().filter((item) => !item.disabled),
  );
  protected readonly activeOption = computed(() => this.enabledItems()[this.active()]);
  protected move(event: KeyboardEvent): void {
    if (this.disabled()) {
      return;
    }
    const items = this.enabledItems();
    if (!items.length) {
      return;
    }
    if (['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) {
      event.preventDefault();
      this.active.update((index) =>
        event.key === 'Home'
          ? 0
          : event.key === 'End'
            ? items.length - 1
            : (index + (event.key === 'ArrowUp' ? -1 : 1) + items.length) % items.length,
      );
    } else if (event.key === 'Enter') {
      event.preventDefault();
      const item = items[this.active()];
      if (item) this.select(item);
    }
  }
  protected select(item: AevkoCommandItem): void {
    if (item.disabled || this.disabled()) {
      return;
    }
    this.value.set(item.id);
    this.activated.emit(item);
  }
}

:host {
  background: var(--aevko-surface, #fff);
  border: 1px solid var(--aevko-border, #e4e4e7);
  display: grid;
  inline-size: min(28rem, 100%);
}
.search {
  border-block-end: 1px solid var(--aevko-border, #e4e4e7);
  padding: 0.5rem;
}
input {
  background: transparent;
  border: 0;
  color: inherit;
  inline-size: 100%;
  min-block-size: 2.5rem;
  padding: 0.5rem;
}
input:focus-visible {
  outline: 2px solid var(--aevko-ring, #a3a3a3);
}
[role='listbox'] {
  display: grid;
  max-block-size: 18rem;
  overflow: auto;
  padding: 0.25rem;
}
[role='option'] {
  align-items: center;
  display: flex;
  gap: 1rem;
  justify-content: space-between;
  padding: 0.625rem;
}
[role='option'][data-active='true'],
[role='option']:hover,
[role='option']:focus-visible {
  background: color-mix(in srgb, currentcolor 10%, var(--aevko-surface, #fff));
  color: var(--aevko-surface-foreground, currentcolor);
  outline: 0;
}
[role='option'][data-active='true'] small,
[role='option']:hover small,
[role='option']:focus-visible small {
  color: inherit;
  opacity: 0.72;
}
[role='option'][aria-disabled='true'] {
  opacity: 0.5;
}
span {
  display: grid;
}
small {
  color: var(--aevko-muted-foreground, #666);
}
kbd {
  font: inherit;
  font-size: 0.75rem;
}
p {
  color: var(--aevko-muted-foreground, #666);
  padding: 1rem;
  text-align: center;
}
